   101|
   102|export default function ProfileScreen() {
   103|  const { width } = useWindowDimensions();
   104|  const router = useRouter();
   105|  const { logout, profileData } = useAuth();
   106|  /* Auth state is intentionally NOT used to gate Owner Login — it is read only for the diagnostic panel below. */
   107|  const { t } = useTranslation();
   108|  const { currentLanguage } = useI18n();
   109|  const { trackAction } = useAnalytics();
   110|
   111|  const balanceQuery = useQuery({
   112|    queryKey: ['wallet-balance', 'profile'],
   113|    queryFn: async () => {
   114|      const { data: { user } } = await supabase.auth.getUser();
   115|      if (!user) return null;
   116|      const { data } = await supabase.from('wallets').select('*').eq('user_id', user.id).single();
   117|      return data;
   118|    },
   119|    staleTime: 1000 * 60 * 2,
   120|    enabled: !!profileData,
   121|  });
   122|
   123|  const classificationQuery = useQuery({
   124|    queryKey: ['member-classification', 'profile'],
   125|    queryFn: async () => {
   126|      const { data: { session } } = await supabase.auth.getSession();
   127|      if (!session?.access_token) return null;
   128|      const result = await getMyClassification(session.access_token);
   129|      return result.ok ? result.classification ?? null : null;
   130|    },
   131|    staleTime: 1000 * 60 * 5,
   132|    enabled: !!profileData && !currentUser.isOwnerOrAdmin,
   133|  });
   134|
   135|  const currentUser = useMemo(() => {
   136|    const pd = profileData;
   137|    const role = ((pd as any)?.role ?? '') as string;
   138|    const isOwnerOrAdmin = role === 'owner' || role === 'admin';
   139|    return {
   140|      id: pd?.id ?? '',
   141|      email: pd?.email ?? '',
   142|      firstName: pd?.firstName ?? '',
   143|      lastName: pd?.lastName ?? '',
   144|      avatar: (pd as any)?.avatar ?? '',
   145|      phone: (pd as any)?.phone ?? '',
   146|      country: (pd as any)?.country ?? '',
   147|      role,
   148|      isOwnerOrAdmin,
   149|      kycStatus: (isOwnerOrAdmin ? 'approved' : (pd?.kycStatus ?? 'pending')) as 'approved' | 'pending' | 'in_review' | 'rejected',
   150|      walletBalance: balanceQuery.data?.available ?? (pd as any)?.walletBalance ?? 0,
   151|      totalInvested: balanceQuery.data?.invested ?? (pd as any)?.totalInvested ?? 0,
   152|      totalReturns: (pd as any)?.totalReturns ?? 0,
   153|    };
   154|  }, [profileData, balanceQuery.data]);
   155|
   156|  const screenSize = getResponsiveSize(width);
   157|  const isCompact = isCompactScreen(screenSize);
   158|  const isXs = isExtraSmallScreen(screenSize);
   159|
   160|  // Treat the signed-in person as an owner session when their role is owner/admin
   161|  // or their email matches the approved owner email. When true, the yellow card
   162|  // stops prompting for a fresh login and opens the owner console instead.
   163|  const ownerEmail = (process.env.EXPO_PUBLIC_OWNER_EMAIL ?? '').trim().toLowerCase();
   164|  const isOwnerSession = currentUser.isOwnerOrAdmin
   165|    || (!!currentUser.email && currentUser.email.trim().toLowerCase() === ownerEmail);
   166|  const ownerCardTitle = isOwnerSession ? 'Owner Console' : 'Owner Login';
   167|  const ownerCardSubtitle = isOwnerSession
   168|    ? 'Signed in — open owner console'
   169|    : 'Direct approved-owner sign in';
   170|
   171|  const openOwnerLogin = (source: string) => {
   172|    if (isOwnerSession) {
   173|      console.log(`[Profile] Owner Console (${source}) tapped -> /admin/ivx-developer-workspace`);
   174|      router.push('/admin/ivx-developer-workspace' as any);
   175|      return;
   176|    }
   177|    console.log(`[Profile] Owner Login (${source}) tapped -> /login?ownerMode=1`);
   178|    router.push({ pathname: '/login', params: { ownerMode: '1' } } as any);
   179|  };
   180|
   181|  // ── OWNER LOGIN DEVICE FIX v5 ─ diagnostic build stamp ───────────────────
   182|  // This marker proves which bundle a device is actually running. If a device
   183|  // does NOT show "v5" it is running an OLD/cached bundle, not this code.
   184|  const OWNER_LOGIN_BUILD = 'OWNER LOGIN DEVICE FIX v5';
   185|  const extra = (Constants.expoConfig?.extra ?? {}) as Record<string, string>;
   186|  const { height: winHeight } = useWindowDimensions();
   187|  const isPad = Platform.OS === 'ios' && (Platform as unknown as { isPad?: boolean }).isPad === true;
   188|  const diag: { key: string; val: string }[] = [
   189|    { key: 'SHOW_OWNER_LOGIN', val: 'true' },
   190|    { key: 'platform', val: Platform.OS },
   191|    { key: 'isAndroid', val: String(Platform.OS === 'android') },
   192|    { key: 'isIOS', val: String(Platform.OS === 'ios') },
   193|    { key: 'isPad/tablet', val: String(isPad) },
   194|    { key: 'screenWidth', val: String(Math.round(width)) },
   195|    { key: 'screenHeight', val: String(Math.round(winHeight)) },
   196|    { key: 'authLoaded', val: String(profileData !== undefined) },
   197|    { key: 'sessionPresent', val: String(!!profileData) },
   198|    { key: 'bundleStamp', val: extra.buildMarker ?? 'n/a' },
   199|    { key: 'appVersion', val: Constants.expoConfig?.version ?? 'n/a' },
   200|  ];
   201|
   202|  // Non-sensitive diagnostic: confirms the Administration section (incl. Owner Login)
   203|  // mounted on this device. No emails, passwords, or tokens are ever logged here.
   204|  useEffect(() => {
   205|    console.log('[Profile] Administration rendered — owner-login-button=true admin-panel-button=true');
   206|  }, []);
   207|
   208|  const handleLogout = () => {
   209|    Alert.alert(
   210|      t('signOut'),
   211|      t('signOutConfirm'),
   212|      [
   213|        { text: t('cancel'), style: 'cancel' },
   214|        { text: t('signOut'), style: 'destructive', onPress: () => { trackAction('logout'); void logout(); } },
   215|      ]
   216|    );
   217|  };
   218|
   219|  const getKYCStatusText = () => {
   220|    switch (currentUser.kycStatus) {
   221|      case 'approved':
   222|        return t('verified');
   223|      case 'pending':
   224|        return t('pendingReview');
   225|      case 'in_review':
