   264|            <Text style={styles.emergencyBannerText}>{OWNER_LOGIN_BUILD}</Text>
   265|            <Text style={styles.emergencyBannerSub}>{Platform.OS} · {Math.round(width)}×{Math.round(winHeight)} · v{Constants.expoConfig?.version ?? '?'}</Text>
   266|          </View>
   267|
   268|          <TouchableOpacity
   269|            style={[styles.ownerLoginButton, { marginHorizontal: isXs ? 16 : 20, padding: isXs ? 14 : 16, marginBottom: 12 }]}
   270|            onPress={() => openOwnerLogin('top')}
   271|            activeOpacity={0.8}
   272|            accessibilityRole="button"
   273|            accessibilityLabel="Owner Login"
   274|            testID="owner-login-button-top"
   275|          >
   276|            <View style={[styles.ownerLoginIcon, { width: isCompact ? 38 : 44, height: isCompact ? 38 : 44 }]}>
   277|              <Shield size={isXs ? 20 : 24} color={Colors.background} />
   278|            </View>
   279|            <View style={{ flex: 1, minWidth: 0 }}>
   280|              <Text style={[styles.ownerLoginTitle, { fontSize: isXs ? 15 : 17 }]}>{ownerCardTitle}</Text>
   281|              <Text style={[styles.ownerLoginSubtitle, { fontSize: isXs ? 11 : 12 }]}>{ownerCardSubtitle}</Text>
   282|            </View>
   283|            <ChevronRight size={isCompact ? 20 : 22} color={Colors.background} />
   284|          </TouchableOpacity>
   285|
   286|          <View style={[styles.diagPanel, { marginHorizontal: isXs ? 16 : 20 }]} testID="owner-login-diagnostic-panel">
   287|            <Text style={styles.diagTitle}>OWNER LOGIN DIAGNOSTIC</Text>
   288|            {diag.map((d) => (
   289|              <View key={d.key} style={styles.diagRow}>
   290|                <Text style={styles.diagKey}>{d.key}</Text>
   291|                <Text style={styles.diagVal}>{d.val}</Text>
   292|              </View>
   293|            ))}
   294|          </View>
   295|
   296|          <View style={[styles.profileCard, { marginHorizontal: isXs ? 16 : 20, padding: isXs ? 16 : 20 }]}>
   297|            <Image
   298|              source={{ uri: currentUser.avatar }}
   299|              style={[styles.avatar, { width: isXs ? 60 : 72, height: isXs ? 60 : 72, borderRadius: isXs ? 30 : 36 }]}
   300|            />
   301|            <View style={styles.profileInfo}>
   302|              <View style={styles.nameRow}>
   303|                <Text style={[styles.userName, { fontSize: isXs ? 17 : 20 }]}>
   304|                  {currentUser.firstName} {currentUser.lastName}
   305|                </Text>
   306|                {currentUser.kycStatus === 'approved' && (
